/*
  TODO_PRODUIT.md T3 (2026-09-03) — closes the TODO_ISSUES.md entry "les taux existent, mais
  paiements et avoirs ne convertissent toujours pas", per that entry's own recorded WHY: a lettrage
  needs a rate PER TRANSACTION -- entered when the payment is recorded and stored on it -- not the
  company's ambient rate, which is exactly what `documentAmountMinor`/`conversionRate`/`conversionRateAsOf`/
  `conversionSource` below are (see `DocumentPayment`'s own schema.prisma comment for the full
  reasoning, and `settlement/convert-payment.ts` for the arithmetic that fills them in).

  `documentAmountMinor` is NOT NULL with no default — every `DocumentPayment` row written BEFORE
  this task exists only because "record-payment" refused any currency but the document's own (see
  invoice-actions.ts's pre-T3 guard), so for every one of them `documentAmountMinor` is trivially
  `amountMinor` itself (no conversion ever applied). Backfilled explicitly below, in its own step,
  rather than a bare `ADD COLUMN ... NOT NULL` — which Postgres refuses outright the moment this
  table holds a single row (a real, non-empty self-hosted install almost certainly does by the time
  it upgrades to this migration) — the same "never a migration that only works on an empty table"
  discipline `sync-schema.ts`'s own callers already hold for a legacy self-hosted DB.

  `DOCUMENT_SETTLED` joins the `WebhookEvent` enum as a plain ADD VALUE — unlike
  20260903000000_generic_document_webhook_events (which had to REMOVE 51 values, and Postgres has no
  `DROP VALUE`, hence that migration's own type-rebuild dance), adding one is directly supported and
  needs no such reconstruction.
*/

-- AlterEnum
ALTER TYPE "WebhookEvent" ADD VALUE 'DOCUMENT_SETTLED';

-- AlterTable: add every new column NULLABLE first — see this file's own header on why
-- `documentAmountMinor` cannot go straight to NOT NULL on a table that may already hold rows.
ALTER TABLE "DocumentPayment" ADD COLUMN     "conversionRate" DECIMAL(65,30),
ADD COLUMN     "conversionRateAsOf" TIMESTAMP(3),
ADD COLUMN     "conversionSource" TEXT,
ADD COLUMN     "documentAmountMinor" INTEGER;

-- Backfill: every pre-existing row was, by construction, paid in the document's own currency (see
-- this file's own header) — its settlement-relevant figure is exactly its own `amountMinor`, and it
-- was never converted, so the three `conversion*` columns rightly stay NULL for it.
UPDATE "DocumentPayment" SET "documentAmountMinor" = "amountMinor" WHERE "documentAmountMinor" IS NULL;

-- Now that every existing row (and any row a concurrent write could have added) is backfilled, the
-- column can safely become NOT NULL for every write from here on.
ALTER TABLE "DocumentPayment" ALTER COLUMN "documentAmountMinor" SET NOT NULL;

-- Supplier reconciliation for received invoices reuses "Client" with a role, carried by a SEPARATE
-- boolean and never by extending "kind". See the `isSupplier` field's own comment in schema.prisma
-- for the WHY: kind/GOVERNMENT is a B2G ROUTING fact, while "is a supplier of this company" is an
-- ORTHOGONAL fact about the INBOUND direction. A client can be both at once, and "kind" cannot carry
-- two independent facts without composite values.
--
-- DEFAULT false, NOT NULL is the deliberate backfill: no EXISTING client is a supplier until
-- reconciliation says so explicitly, automatically or by hand
-- (received-invoices/supplier-reconciliation.ts). Purely additive; this migration never sets it.
ALTER TABLE "Client" ADD COLUMN "isSupplier" BOOLEAN NOT NULL DEFAULT false;

-- Repairs an ORDERING MINE laid by two migrations written in parallel:
--   * 20260902234040_payment_conversion_and_document_settled runs
--     `ALTER TYPE "WebhookEvent" ADD VALUE 'DOCUMENT_SETTLED'` -- timestamped 23:40 on the 2nd.
--   * 20260903000000_generic_document_webhook_events REBUILDS the WebhookEvent type
--     (CREATE TYPE _new / cast / rename, the only way to remove values in Postgres) from the value
--     list AS IT STOOD when that file was written -- WITHOUT DOCUMENT_SETTLED, which did not exist
--     yet.
-- On this repository's two live databases the rebuild really did run before the ADD VALUE, in commit
-- order, and everything is sound. But on a FRESH database -- CI, a new install, or the one
-- sync-schema.ts brings up to date -- `migrate deploy` replays the directories in LEXICOGRAPHIC
-- timestamp order: the ADD VALUE first, then the rebuild, which DESTROYS the value by recreating the
-- type without it. Proven on a throwaway database on 2026-09-03: the whole deploy reported
-- "successful", and pg_enum came out with no DOCUMENT_SETTLED. The first settled document would have
-- crashed the webhook dispatch.
--
-- Why THIS fix and not another: renaming the earlier directory would break checksum verification on
-- databases where it is already applied under its current name, and editing the rebuild's CREATE
-- TYPE would do the same. An ADDITIVE, IDEMPOTENT migration (IF NOT EXISTS) is the only shape that
-- is an exact no-op on healthy databases AND a complete repair on fresh ones.
ALTER TYPE "WebhookEvent" ADD VALUE IF NOT EXISTS 'DOCUMENT_SETTLED';

